<?php declare(strict_types=1); /** @var Closure(mixed): string $escape */ $allUnits=$unit['id']===null;$labels=['pending'=>'Pendente','completed'=>'Concluído','cancelled'=>'Cancelado']; ?>
<div class="actions"><div><span class="status">CRM · <?= $escape($unit['name']) ?></span><h1>Follow-ups</h1><p class="meta">Agenda e histórico de acompanhamento dos contatos.</p></div></div>
<?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<div class="row g-3 followup-summary"><div class="col-md-4"><a href="?status=pending&amp;period=overdue" class="followup-card overdue"><span>Atrasados</span><strong><?= $escape($summary['overdue']) ?></strong></a></div><div class="col-md-4"><a href="?status=pending&amp;period=today" class="followup-card today"><span>Para hoje</span><strong><?= $escape($summary['today']) ?></strong></a></div><div class="col-md-4"><a href="?status=pending&amp;period=future" class="followup-card future"><span>Futuros</span><strong><?= $escape($summary['future']) ?></strong></a></div></div>
<form method="get" action="<?= $escape($basePath) ?>/crm/follow-ups" class="followup-filters"><input class="followup-search" name="q" value="<?= $escape($search) ?>" placeholder="Buscar contato, telefone, e-mail ou ação"><select class="form-select" name="status"><option value="">Todas as situações</option><?php foreach($labels as $value=>$label):?><option value="<?= $escape($value) ?>" <?= $selectedStatus===$value?'selected':'' ?>><?= $escape($label) ?></option><?php endforeach;?></select><select class="form-select" name="period"><option value="">Todos os períodos</option><option value="due" <?= $selectedPeriod==='due'?'selected':'' ?>>Atrasados e para hoje</option><option value="overdue" <?= $selectedPeriod==='overdue'?'selected':'' ?>>Atrasados</option><option value="today" <?= $selectedPeriod==='today'?'selected':'' ?>>Hoje</option><option value="future" <?= $selectedPeriod==='future'?'selected':'' ?>>Futuros</option></select><select class="form-select" name="responsible"><option value="">Todos os atendentes</option><?php foreach($responsibles as $person):?><option value="<?= $escape($person['id']) ?>" <?= (int)$selectedResponsible===(int)$person['id']?'selected':'' ?>><?= $escape($person['name']) ?></option><?php endforeach;?></select><button type="submit">Filtrar</button><a class="button-secondary" href="<?= $escape($basePath) ?>/crm/follow-ups?status=pending">Limpar</a></form><p class="meta followup-result-count"><?= $escape($resultCount) ?> resultado(s) encontrado(s).</p>
<div class="table-responsive"><table><thead><tr><th>Data/Hora</th><th>Contato</th><?php if($allUnits):?><th>Unidade</th><?php endif;?><th>Próxima ação</th><th>Atendente</th><th>Observações</th><th>Situação</th><th></th></tr></thead><tbody><?php if($followUps===[]):?><tr><td colspan="<?= $allUnits?'8':'7' ?>">Nenhum follow-up encontrado.</td></tr><?php endif;?><?php foreach($followUps as $item):?><?php $overdue=$item['status']==='pending'&&strtotime((string)$item['scheduled_at'])<strtotime('today');?><tr class="<?= $overdue?'followup-row-overdue':'' ?>"><td><?= $escape(date('d/m/Y H:i',strtotime((string)$item['scheduled_at']))) ?><?php if($overdue):?><br><span class="overdue-label">Atrasado</span><?php endif;?></td><td><strong><?= $escape($item['contact_name']) ?></strong></td><?php if($allUnits):?><td><?= $escape($item['unit_name']) ?></td><?php endif;?><td><?= $escape($item['action']) ?></td><td><?= $escape($item['responsible_name']) ?></td><td><?= nl2br($escape($item['notes'])) ?></td><td><span class="followup-status followup-<?= $escape($item['status']) ?>"><?= $escape($labels[$item['status']]??$item['status']) ?></span></td><td><?php if(!$allUnits&&$item['status']==='pending'):?><div class="followup-actions"><form method="post" action="<?= $escape($basePath) ?>/crm/follow-ups/<?= $escape($item['id']) ?>/status"><?= $csrfField ?><input type="hidden" name="status" value="completed"><button class="btn btn-sm btn-success" type="submit">Concluir</button></form><form method="post" action="<?= $escape($basePath) ?>/crm/follow-ups/<?= $escape($item['id']) ?>/status"><?= $csrfField ?><input type="hidden" name="status" value="completed"><input type="hidden" name="create_next" value="1"><button class="btn btn-sm btn-outline-secondary" type="submit">Concluir e criar próximo</button></form><form method="post" action="<?= $escape($basePath) ?>/crm/follow-ups/<?= $escape($item['id']) ?>/status"><?= $csrfField ?><input type="hidden" name="status" value="cancelled"><button class="btn btn-sm btn-outline-secondary" type="submit">Cancelar</button></form></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
